create or replace function public.audit_event_append_only_guard() returns trigger language plpgsql set search_path = public, pg_temp as $$ begin raise exception 'audit_events_append_only'; end; $$; create or replace function public.discovery_source_permission_active(p_source_id uuid) returns boolean language sql stable security invoker set search_path = public, pg_temp as $$ select exists (select 1 from public.discovery_permission_evidence evidence where evidence.source_id = p_source_id and evidence.status in ('verified', 'approved') and evidence.verified_at is not null and (evidence.expires_at is null or evidence.expires_at > now())); $$; create or replace function public.discovery_source_permission_guard() returns trigger language plpgsql set search_path = public, pg_temp as $$ begin if new.enabled = true and (new.policy_mode = 'explicit_permission' or coalesce((new.config ->> 'require_permission_reference')::boolean, false) = true) and not public.discovery_source_permission_active(new.id) then raise exception 'discovery_permission_evidence_required'; end if; return new; end; $$; drop trigger if exists discovery_source_permission_guard on public.discovery_sources; create trigger discovery_source_permission_guard before insert or update of enabled, policy_mode, config on public.discovery_sources for each row execute function public.discovery_source_permission_guard(); update public.discovery_sources set enabled = false, updated_at = now() where enabled = true and (policy_mode = 'explicit_permission' or coalesce((config ->> 'require_permission_reference')::boolean, false) = true) and not public.discovery_source_permission_active(id); create or replace function public.dashboard_apply_action(p_action text, p_entity_id uuid, p_notes text default null, p_enabled boolean default null, p_status text default null, p_actor_id text default null, p_correlation_id text default null) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$ declare before_state jsonb; after_state jsonb; audit_entity_type text; begin if coalesce(nullif(trim(p_actor_id), ''), '') = '' then raise exception 'dashboard_actor_required'; end if; if coalesce(nullif(trim(p_correlation_id), ''), '') = '' then raise exception 'dashboard_correlation_required'; end if; case p_action when 'review_approve', 'review_reject' then select jsonb_build_object('status', status, 'decision', decision) into before_state from public.review_queue where id = p_entity_id for update; if before_state is null then return jsonb_build_object('ok', false, 'error', 'review_not_found'); end if; update public.review_queue set status = case when p_action = 'review_approve' then 'approved' else 'rejected' end, decision = case when p_action = 'review_approve' then 'approved' else 'rejected' end, reviewed_at = now(), notes = coalesce(left(p_notes, 2000), notes) where id = p_entity_id returning jsonb_build_object('status', status, 'decision', decision, 'reviewed_at', reviewed_at) into after_state; audit_entity_type := 'review_queue'; when 'job_retry' then select jsonb_build_object('status', status, 'attempts', attempts, 'max_attempts', max_attempts) into before_state from public.jobs where id = p_entity_id for update; if before_state is null then return jsonb_build_object('ok', false, 'error', 'job_not_found'); end if; if coalesce((before_state ->> 'attempts')::integer, 0) >= coalesce((before_state ->> 'max_attempts')::integer, 3) then return jsonb_build_object('ok', false, 'error', 'max_attempts_reached'); end if; update public.jobs set status = 'queued', error_message = null, available_at = now(), locked_at = null, locked_by = null, lease_expires_at = null where id = p_entity_id returning jsonb_build_object('status', status, 'attempts', attempts, 'available_at', available_at) into after_state; audit_entity_type := 'jobs'; when 'publication_cancel' then select jsonb_build_object('status', status) into before_state from public.publication_jobs where id = p_entity_id for update; if before_state is null then return jsonb_build_object('ok', false, 'error', 'publication_not_found'); end if; if before_state ->> 'status' in ('finished', 'cancelled') then return jsonb_build_object('ok', false, 'error', 'publication_terminal'); end if; update public.publication_jobs set status = 'cancelled', finished_at = now() where id = p_entity_id returning jsonb_build_object('status', status, 'finished_at', finished_at) into after_state; audit_entity_type := 'publication_jobs'; when 'discovery_toggle' then select jsonb_build_object('enabled', enabled) into before_state from public.discovery_sources where id = p_entity_id for update; if before_state is null then return jsonb_build_object('ok', false, 'error', 'discovery_source_not_found'); end if; if p_enabled is null then return jsonb_build_object('ok', false, 'error', 'discovery_enabled_required'); end if; update public.discovery_sources set enabled = p_enabled, updated_at = now() where id = p_entity_id returning jsonb_build_object('enabled', enabled, 'updated_at', updated_at) into after_state; audit_entity_type := 'discovery_sources'; when 'lead_status' then if p_status not in ('new', 'qualified', 'contacted', 'meeting', 'negotiation', 'won', 'lost', 'nurture') then return jsonb_build_object('ok', false, 'error', 'invalid_lead_status'); end if; select jsonb_build_object('status', status) into before_state from public.leads where id = p_entity_id for update; if before_state is null then return jsonb_build_object('ok', false, 'error', 'lead_not_found'); end if; update public.leads set status = p_status, notes = coalesce(left(p_notes, 4000), notes), updated_at = now() where id = p_entity_id returning jsonb_build_object('status', status, 'updated_at', updated_at) into after_state; audit_entity_type := 'leads'; else return jsonb_build_object('ok', false, 'error', 'unsupported_action'); end case; insert into public.audit_events (event_type, entity_type, entity_id, actor_type, actor_id, payload, correlation_id, before_state, after_state, reason) values ('dashboard_action', audit_entity_type, p_entity_id, 'dashboard_session', p_actor_id, jsonb_build_object('action', p_action), p_correlation_id, before_state, after_state, nullif(left(p_notes, 4000), '')); return jsonb_build_object('ok', true, 'action', p_action, 'updated', after_state, 'correlation_id', p_correlation_id); end; $$; revoke all on function public.dashboard_apply_action(text, uuid, text, boolean, text, text, text) from public; grant execute on function public.dashboard_apply_action(text, uuid, text, boolean, text, text, text) to service_role;
